<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../helpers/auth.php';require_once __DIR__.'/../helpers/redirect.php';require_once __DIR__.'/../models/LogAktivitas.php';
class PengaturanController{public function index(){require_role('admin');$db=Database::getConnection();$s=$db->prepare("SELECT nilai FROM pengaturan WHERE kunci='denda_per_jam' LIMIT 1");$s->execute();$nilai=$s->fetchColumn();$tarif=$nilai===false?208.33:(float)$nilai;$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$tarif=(float)($_POST['denda_per_jam']??0);if($tarif<0)$error='Denda tidak boleh negatif.';else{$s=$db->prepare("UPDATE pengaturan SET nilai=? WHERE kunci='denda_per_jam'");$s->execute([$tarif]);(new LogAktivitas($db))->add(current_user()['id'],'Mengubah denda per jam','Pengaturan');flash('success','Pengaturan berhasil disimpan.');redirect('pengaturan');}}require __DIR__.'/../views/info/pengaturan.php';}}
